def _resource_dir():
    """Directory of build resources. In the .exe (PyInstaller onefile) this is the unpacked
    temporary directory `sys._MEIPASS`; normally it's the script directory."""
    return getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))


def _app_dir():
    """Directory 'next to the app' for PERSISTENT data (rules). In the .exe this is the
    directory containing the .exe file (survives a restart); in script mode - the script directory."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))


def reveal_in_explorer(folder, select_file=None):
    """Open `folder` in Explorer (selecting `select_file` when given) AND pull that window to
    the front. Returns (ok, error, fronted).

    WHY THIS IS NOT `os.startfile(folder)`. Measured 2026-09-12 on the live build: startfile
    raises nothing and the endpoint answers {"ok": true}, yet nothing appears. Windows only lets
    the process that OWNS the foreground hand it over, and at the moment of the click that is the
    browser, not us. So the window opens BEHIND everything (a new folder) or, when that folder is
    already open, Explorer merely tries to activate the existing window and the attempt is
    refused - on screen: absolutely nothing. Both look exactly like a broken button.

    The fix has two halves. `explorer.exe /select,<file>` is used instead of startfile because it
    both opens the folder and highlights the file the button is about (the log), and because it
    reuses an already-open window instead of piling up duplicates. Then the window is fronted by
    hand with the AttachThreadInput trick: we borrow the input queue of whoever holds the
    foreground, which makes SetForegroundWindow legal for the length of that call.

    Everything here is best-effort and never raises: `fronted=False` is an honest answer the panel
    can turn into "look at the taskbar", not a failure."""
    err = None
    try:
        os.makedirs(folder, exist_ok=True)     # /diag/open already did this; this one never did
    except Exception as e:
        err = str(e)[:200]
    try:
        if select_file and os.path.exists(select_file):
            # The comma belongs to the /select switch and MUST stay glued to it in its own argv
            # entry - "explorer /select, C:\..." with the path separate is the documented form.
            subprocess.Popen(["explorer.exe", "/select,", os.path.normpath(select_file)])
        else:
            subprocess.Popen(["explorer.exe", os.path.normpath(folder)])
    except Exception as e:
        return (False, str(e)[:200], False)
    return (True, err, _front_explorer_window(folder))


def _front_explorer_window(folder, deadline=2.5):
    """Best-effort: bring the Explorer window showing `folder` to the front. True when it worked.

    Windows are matched by TITLE, because an Explorer window titles itself either with the folder
    name or with its full path depending on a system setting - both contain the folder name, so
    that is what we look for. Anything unexpected (not Windows, no ctypes, no window) answers
    False instead of raising: failing to raise a window is not a failure to open it."""
    try:
        import ctypes
        from ctypes import wintypes
        u32 = ctypes.windll.user32
        want = os.path.basename(os.path.normpath(folder)).lower()
        full = os.path.normpath(folder).lower()
        if not want:
            return False

        def _title(h):
            b = ctypes.create_unicode_buffer(512)
            u32.GetWindowTextW(h, b, 512)
            return b.value or ""

        CB = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
        hits = []

        def _cb(h, _):
            cls = ctypes.create_unicode_buffer(64)
            u32.GetClassNameW(h, cls, 64)
            if cls.value in ("CabinetWClass", "ExploreWClass") and u32.IsWindowVisible(h):
                t = _title(h).lower()
                if full in t or t.startswith(want):
                    hits.append(h)
            return True

        t0 = time.time()
        hwnd = None
        while time.time() - t0 < deadline:          # the window needs a moment to exist
            hits.clear()
            u32.EnumWindows(CB(_cb), 0)
            if hits:
                hwnd = hits[0]
                break
            time.sleep(0.15)
        if not hwnd:
            return False
        u32.ShowWindow(hwnd, 9)                     # SW_RESTORE - unminimise if it was minimised
        cur = ctypes.windll.kernel32.GetCurrentThreadId()
        tgt = u32.GetWindowThreadProcessId(u32.GetForegroundWindow(), None)
        u32.AttachThreadInput(cur, tgt, True)
        try:
            u32.BringWindowToTop(hwnd)
            return bool(u32.SetForegroundWindow(hwnd))
        finally:
            u32.AttachThreadInput(cur, tgt, False)
    except Exception:
        return False


def _front_window_by_title(prefix, deadline=0.6):
    """Best-effort: wyciągnij na wierzch pierwsze widoczne okno, którego TYTUŁ zaczyna się od
    `prefix`. True, gdy się udało.

    Rodzeństwo `_front_explorer_window` (ta sama sztuczka z AttachThreadInput), tyle że KLASA okna
    jest dowolna. Po co osobno: panel RibbitFlipa jest STRONĄ w cudzej przeglądarce, więc jego okno
    ma klasę Chrome'a, Edge'a albo Firefoksa — czyli akurat to, po czym tamta funkcja filtruje.
    Zostaje tytuł: strona nazywa się „RibbitFlip — panel", a przeglądarka dokleja do niego swoją
    nazwę z tyłu, więc pasuje początek, nie całość.

    Krótszy termin niż przy Eksploratorze (0,6 s zamiast 2,5 s), bo tu NIKT właśnie nie otwiera
    okna — ono albo stoi, albo go nie ma. Ta funkcja jest wołana ze skrótu robiącego zrzut, czyli
    z chwili, w której człowiek czeka. Porażka nie jest błędem: panel może być zamknięty, a zrzut
    i tak jest zapisany."""
    want = str(prefix or "").strip().lower()
    if not want:
        return False
    try:
        import ctypes
        from ctypes import wintypes
        u32 = ctypes.windll.user32

        CB = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
        hits = []

        def _cb(h, _):
            if not u32.IsWindowVisible(h):
                return True
            b = ctypes.create_unicode_buffer(512)
            u32.GetWindowTextW(h, b, 512)
            if (b.value or "").strip().lower().startswith(want):
                hits.append(h)
            return True

        t0 = time.time()
        hwnd = None
        while True:
            hits.clear()
            u32.EnumWindows(CB(_cb), 0)
            if hits:
                hwnd = hits[0]
                break
            if time.time() - t0 >= deadline:
                break
            time.sleep(0.15)
        if not hwnd:
            return False
        u32.ShowWindow(hwnd, 9)                     # SW_RESTORE - unminimise if it was minimised
        cur = ctypes.windll.kernel32.GetCurrentThreadId()
        tgt = u32.GetWindowThreadProcessId(u32.GetForegroundWindow(), None)
        u32.AttachThreadInput(cur, tgt, True)
        try:
            u32.BringWindowToTop(hwnd)
            return bool(u32.SetForegroundWindow(hwnd))
        finally:
            u32.AttachThreadInput(cur, tgt, False)
    except Exception:
        return False


def _tytul_okna_na_wierzchu():
    """Tytuł okna, które ma teraz skupienie — albo pusty napis. Nazwa planszy ze zrzutu bierze się
    właśnie stąd: w chwili naciśnięcia skrótu na wierzchu jest gra, więc „Sol Cesto" trafia do
    panelu samo, zamiast czekać na wpisanie ręką po powrocie do panelu."""
    try:
        import ctypes
        u32 = ctypes.windll.user32
        h = u32.GetForegroundWindow()
        if not h:
            return ""
        b = ctypes.create_unicode_buffer(512)
        u32.GetWindowTextW(h, b, 512)
        t = (b.value or "").strip()
        # NASZE WŁASNE OKNA NIE SĄ NAZWĄ GRY (2026-09-26). Skupienie ma czasem okno nakładki
        # (edytor obszaru, nakładka kapsla) albo panel — plansza nazywała się wtedy
        # „RibbitFlip · RFOVL-76623b". Pusta nazwa daje zwykłe „Plansza N".
        if t.startswith(("RFSKAN-", "RFOVL-")) or "RibbitFlip" in t:
            return ""
        return t
    except Exception:
        return ""


# ── The app's own log ──────────────────────────────────────────────────────────────────────
# In a windowed build every print() lands in this file, and until 2026-08-26 the handle was a
# plain append with no ceiling: it only ever grew. One print() on a repeating fault (a puck that
# keeps dropping the link, a handler raising on every request) leaves tens of MB next to the
# .exe — measured here at 20.7 MB — and nobody notices, because nobody opens the log until
# something breaks. Same treatment as the REST log: a size cap with a couple of generations
# behind it, so the part that explains a crash survives and the ceiling is a known number.
APP_LOG_NAME = "ribbitflip.log"
APP_LOG_MAX_BYTES = 2 * 1024 * 1024   # per generation
APP_LOG_GENERATIONS = 3               # ribbitflip.log + .log.1 + .log.2 -> 6 MB ceiling
APP_LOG_MAX_DAYS = 30                 # checked only when rotating, exactly like the REST log


def _app_log_paths(base):
    return [base] + ["%s.%d" % (base, i) for i in range(1, APP_LOG_GENERATIONS)]


def _app_log_rotate(base):
    """Roll base -> base.1 -> base.2 and drop the oldest. The file MUST be closed first —
    Windows refuses to rename a handle that is still open."""
    paths = _app_log_paths(base)
    try:
        os.remove(paths[-1])
    except OSError:
        pass
    for i in range(len(paths) - 1, 0, -1):
        try:
            os.replace(paths[i - 1], paths[i])
        except OSError:
            pass
    cutoff = time.time() - APP_LOG_MAX_DAYS * 86400.0
    for p in paths[1:]:
        try:
            if os.path.getmtime(p) < cutoff:
                os.remove(p)
                continue
            # A generation GROSSLY over the cap can only come from a build that had no cap at
            # all (the 20.7 MB file this change was written for). Rolling it into .1 and leaving
            # it there would make the advertised 6 MB ceiling a lie for another 30 days. The
            # threshold is 2x, not 1x: a normally rotated generation always sits a line or two
            # PAST the cap, so a strict test would delete every rotation the moment it happened.
            if os.path.getsize(p) > 2 * APP_LOG_MAX_BYTES:
                os.remove(p)
        except OSError:
            pass


class _RollingLog:
    """The sink behind sys.stdout/sys.stderr in a windowed build. Behaves like the file it
    replaces and rolls over once the current generation passes APP_LOG_MAX_BYTES. One instance
    serves both streams, so its lock also keeps two threads from interleaving half-lines.
    Nothing here may raise: a failing print() inside an exception handler hides the real fault."""

    def __init__(self, path):
        self._path = path
        self._lock = threading.RLock()
        self._n = 0
        self._f = None
        self._devnull = False
        try:
            if os.path.getsize(path) >= APP_LOG_MAX_BYTES:
                _app_log_rotate(path)     # a run always starts inside the budget
        except OSError:
            pass
        self._open()

    def _open(self):
        try:
            self._f = open(self._path, "a", encoding="utf-8", errors="replace", buffering=1)
            self._n = os.path.getsize(self._path)
            self._devnull = False
        except Exception:
            self._f = open(os.devnull, "w")   # swallow rather than break every print()
            self._n = 0
            self._devnull = True

    def _roll(self):
        """Under the lock, right after a write. Confirms the size on disk before touching
        anything: the counter counts characters, the cap is in bytes."""
        if self._devnull:
            return
        try:
            self._f.flush()
        except Exception:
            pass
        try:
            real = os.path.getsize(self._path)
        except OSError:
            real = self._n
        if real < APP_LOG_MAX_BYTES:
            self._n = real                # mostly-ASCII text: the counter ran ahead, not behind
            return
        try:
            self._f.close()
        except Exception:
            pass
        _app_log_rotate(self._path)
        self._open()

    def write(self, s):
        if not isinstance(s, str):
            s = str(s)
        with self._lock:
            try:
                self._f.write(s)
            except Exception:
                return len(s)
            self._n += len(s)
            if self._n >= APP_LOG_MAX_BYTES:
                self._roll()
            return len(s)

    def writelines(self, lines):
        for line in lines:
            self.write(line)

    def flush(self):
        with self._lock:
            try:
                self._f.flush()
            except Exception:
                pass

    def close(self):
        with self._lock:
            try:
                self._f.close()
            except Exception:
                pass

    def isatty(self):
        return False

    def fileno(self):
        with self._lock:
            return self._f.fileno()

    @property
    def closed(self):
        return getattr(self.__dict__.get("_f"), "closed", False)

    def __getattr__(self, name):
        f = self.__dict__.get("_f")       # guarded: __getattr__ fires before _f exists too
        if f is None:
            raise AttributeError(name)
        return getattr(f, name)


def _ensure_std_streams():
    """A windowed PyInstaller build (console=False) has sys.stdout/stderr == None,
    so every print() in this module would raise. Route them to a rolling log file
    next to the app (falls back to os.devnull). No-op with a real console (dev)."""
    if sys.stdout is not None and sys.stderr is not None:
        return
    sink = None
    try:
        sink = _RollingLog(os.path.join(_app_dir(), APP_LOG_NAME))
    except Exception:
        try:
            sink = open(os.devnull, "w")
        except Exception:
            return
    if sys.stdout is None:
        sys.stdout = sink
    if sys.stderr is None:
        sys.stderr = sink


_ensure_std_streams()


