def sanitize_midi_global(cfg):
    """The global MIDI/OSC file as it is allowed to exist — the MIDI port, the default OSC target
    and the named devices.

    Exists for the bundle. `apply_bundle` used to write `app_config.midiGlobal` to disk verbatim,
    which was harmless while the file held three scalars and stopped being harmless the moment it
    started carrying a LIST somebody else's machine wrote. A malformed row would then sit in
    Settings/ until the next start, and only be dropped there — the file and the running app
    would disagree in between."""
    c = cfg if isinstance(cfg, dict) else {}
    try:
        pi = int(c.get("midiPortIndex", -1))
    except Exception:
        pi = -1
    try:
        port = int(c.get("oscPort", 9000))
    except Exception:
        port = 9000
    if not (1 <= port <= 65535):
        port = 9000
    return {"midiPortIndex": pi,
            "oscHost": (str(c.get("oscHost") or "").strip()[:120] or "127.0.0.1"),
            "oscPort": port,
            "oscTargets": OscEmitter.sanitize_targets(c.get("oscTargets"))}


def save_midi_global(cfg):
    try:
        os.makedirs(os.path.dirname(MIDI_GLOBAL_FILE), exist_ok=True)
        tmp = MIDI_GLOBAL_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        os.replace(tmp, MIDI_GLOBAL_FILE)
    except Exception as e:
        print(f"[zapis midi-global blad] {e}")


