              # zostaje przy jednym, bo jest przełącznikiem: drugie naciśnięcie by je cofnęło.
              {"label": "Głośniej", "icon": "🔊", "spec": "media_volume_up", "sequence": "", "rep": 5},
              {"label": "Ciszej", "icon": "🔉", "spec": "media_volume_down", "sequence": "", "rep": 5},
